{"file_text": "using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEgg yolks\nPecorino Romano\nBlack pepper", Steps = "1. Cook pasta in salted boiling water.\n2. Crisp guanciale in a pan.\n3. Whisk egg yolks with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or bake chicken until charred.\n3. Sauté garlic and ginger in oil.\n4. Add tomato sauce and spices, simmer 15 minutes.\n5. Add cream and cooked chicken.\n6. Simmer 10 more minutes. Serve with rice or naan.", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Biryani", Category = "Indian", Ingredients = "Basmati rice\nMixed vegetables\nOnions\nYogurt\nBiryani masala\nSaffron\nMint\nCilantro\nGhee", Steps = "1. Soak rice for 30 minutes, then parboil.\n2. Fry sliced onions until golden.\n3. Layer vegetables, rice, fried onions, and herbs.\n4. Add saffron milk and ghee.\n5. Cover and cook on low heat for 25 minutes.\n6. Gently mix and serve with raita.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Tacos al Pastor", Category = "Mexican", Ingredients = "Pork shoulder\nPineapple\nAchiote paste\nChili peppers\nCorn tortillas\nOnion\nCilantro\nLime", Steps = "1. Marinate pork in achiote and chili mixture overnight.\n2. Grill pork with pineapple slices.\n3. Slice pork thinly.\n4. Warm tortillas on a griddle.\n5. Assemble tacos with pork, pineapple, onion, and cilantro.\n6. Squeeze lime over top and serve.", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in diced onion, jalapeño, tomato, and cilantro.\n4. Add lime juice, garlic, and salt.\n5. Taste and adjust seasoning.\n6. Serve immediately with tortilla chips.", AverageRating = 4.4, RatingCount = 25 },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Preheat oven to 425°F (220°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold chocolate mixture into eggs.\n5. Add flour and vanilla, mix gently.\n6. Pour into greased ramekins and bake 12-14 minutes.\n7. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "Ladyfinger biscuits\nEspresso\nMascarpone\nEggs\nSugar\nCocoa powder\nMarsala wine", Steps = "1. Brew espresso and let cool, mix with Marsala.\n2. Whisk egg yolks and sugar until pale.\n3. Fold in mascarpone cheese.\n4. Whip egg whites and fold into mixture.\n5. Dip ladyfingers in espresso and layer in dish.\n6. Spread mascarpone mixture over layers.\n7. Refrigerate 4+ hours. Dust with cocoa before serving.", AverageRating = 4.7, RatingCount = 22 },
    };

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
        return recipe;
    }
}
