@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (SubmittedRecipe is not null)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@SubmittedRecipe.Title</strong>" has been added.</p>
            <a href="/recipe/@SubmittedRecipe.Id" class="btn btn-primary me-2">View Recipe</a>
            <button class="btn btn-outline-secondary" @onclick="ResetForm">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Submission.Ingredients" placeholder="One ingredient per line" />
                <div class="form-text">Enter one ingredient per line.</div>
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="8" @bind-Value="Submission.Steps" placeholder="1. First step&#10;2. Second step&#10;3. Third step" />
                <div class="form-text">Number each step for clarity.</div>
            </div>

            <button type="submit" class="btn btn-success btn-lg" disabled="@(!IsValid)">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private Recipe? SubmittedRecipe { get; set; }

    private bool IsValid => !string.IsNullOrWhiteSpace(Submission.Title)
        && !string.IsNullOrWhiteSpace(Submission.Category)
        && !string.IsNullOrWhiteSpace(Submission.Ingredients)
        && !string.IsNullOrWhiteSpace(Submission.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        SubmittedRecipe = RecipeService.AddRecipe(Submission);
    }

    private void ResetForm()
    {
        Submission = new RecipeSubmission();
        SubmittedRecipe = null;
    }
}

